from __future__ import annotations

import math
import os
from dataclasses import dataclass
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
from numpy.polynomial.legendre import legder, legval  # noqa: E402
from scipy.linalg import solve  # noqa: E402
from scipy.spatial import cKDTree  # noqa: E402


ORDERS = [4, 6]
NODE_COUNTS = [50, 100, 500, 1000, 2000]
EVAL_SIZE = 500
SEED = 12
NUGGET = 1e-12
DOMAIN_LOW = -1.0
DOMAIN_HIGH = 1.0


def target_velocity(x: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    x0 = x[:, 0]
    x1 = x[:, 1]
    u = (
        3.0 * x1**2
        + 12.0 * np.pi
        * np.sin(2.0 * np.pi * x0)
        * np.sin(4.0 * np.pi * x1)
    )
    v = (
        -4.0 * x0**3
        + 6.0 * np.pi
        * np.cos(2.0 * np.pi * x0)
        * np.cos(4.0 * np.pi * x1)
    )
    return u, v


def relative_l2(reference: np.ndarray, approx: np.ndarray) -> float:
    return float(
        np.linalg.norm(reference - approx) / np.linalg.norm(reference)
    )


def distinct_uniform_points(
    rng: np.random.Generator,
    n: int,
    low: float,
    high: float,
    dim: int = 2,
) -> np.ndarray:
    points: list[tuple[float, ...]] = []
    seen: set[tuple[float, ...]] = set()
    while len(points) < n:
        batch = rng.uniform(low, high, size=(max(32, n - len(points)), dim))
        for row in batch:
            key = tuple(float(v) for v in row)
            if key not in seen:
                seen.add(key)
                points.append(key)
                if len(points) == n:
                    break
    return np.asarray(points, dtype=float)


def total_degree_indices(max_degree: int) -> list[tuple[int, int]]:
    out: list[tuple[int, int]] = []
    for total in range(max_degree + 1):
        for a in range(total + 1):
            out.append((a, total - a))
    return out


def poly_count(dim: int, degree: int) -> int:
    if degree < 0:
        return 0
    return math.comb(dim + degree, dim)


def divfree_poly_rank(dim: int, degree: int, row_count: int) -> int:
    rank = dim * poly_count(dim, degree) - poly_count(dim, degree - 1)
    return min(rank, row_count)


def legendre_values_and_derivatives(
    x: np.ndarray, degree: int
) -> tuple[list[np.ndarray], list[np.ndarray]]:
    vals: list[np.ndarray] = []
    ders: list[np.ndarray] = []
    for n in range(degree + 1):
        coeff = np.zeros(n + 1)
        coeff[-1] = 1.0
        vals.append(legval(x, coeff))
        if n == 0:
            ders.append(np.zeros_like(x))
        else:
            ders.append(legval(x, legder(coeff)))
    return vals, ders


def divfree_polynomial_stack(
    points: np.ndarray, poly_order: int
) -> tuple[np.ndarray, list[tuple[int, int]]]:
    x = points[:, 0]
    y = points[:, 1]
    alpha = total_degree_indices(poly_order + 1)
    leg_x, dleg_x = legendre_values_and_derivatives(x, poly_order + 1)
    leg_y, dleg_y = legendre_values_and_derivatives(y, poly_order + 1)
    dphidx_cols = []
    dphidy_cols = []
    for a, b in alpha:
        dphidx_cols.append(dleg_x[a] * leg_y[b])
        dphidy_cols.append(leg_x[a] * dleg_y[b])
    dphidx = np.column_stack(dphidx_cols)
    dphidy = np.column_stack(dphidy_cols)
    values = np.concatenate([dphidy, -dphidx], axis=0)
    return values, alpha


def df_poly_basis_from_legendre(
    points: np.ndarray,
    poly_order: int,
    center: np.ndarray | None = None,
    scale: float | None = None,
) -> tuple[
    np.ndarray, np.ndarray, float, list[tuple[int, int]], np.ndarray
]:
    if center is None:
        center_arr = np.mean(points, axis=0)
    else:
        center_arr = np.asarray(center, dtype=float)
    shifted = points - center_arr[None, :]
    if scale is None:
        scale_val = max(
            float(np.max(np.linalg.norm(shifted, axis=1))), 1.0
        )
    else:
        scale_val = max(float(scale), np.finfo(float).eps)
    xi = shifted / scale_val
    raw_values, alpha = divfree_polynomial_stack(xi, poly_order)
    raw_values = raw_values / scale_val
    rank = divfree_poly_rank(2, poly_order, raw_values.shape[0])
    _, singular_values, vh = np.linalg.svd(raw_values, full_matrices=False)
    if singular_values.size == 0 or rank == 0:
        return (
            np.zeros((raw_values.shape[0], 0)),
            center_arr,
            scale_val,
            alpha,
            np.zeros((raw_values.shape[1], 0)),
        )
    rank_tol = 1e-10 * max(
        float(singular_values[0]), np.finfo(float).eps
    )
    kept = singular_values[:rank]
    inv_kept = np.where(kept > rank_tol, 1.0 / kept, 0.0)
    transform = vh[:rank].T * inv_kept
    values = raw_values @ transform
    return values, center_arr, scale_val, alpha, transform


def df_phs_blocks(
    x: np.ndarray, y: np.ndarray, degree: int
) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    dx = x[:, 0][:, None] - y[:, 0][None, :]
    dy = x[:, 1][:, None] - y[:, 1][None, :]
    r = np.sqrt(np.maximum(dx**2 + dy**2, 0.0))
    re = np.maximum(r, 1e-14)
    lap_scalar = degree * degree * re ** (degree - 2)
    full_diag = -lap_scalar
    hxx = (
        degree * (degree - 2) * re ** (degree - 4) * dx**2
        + degree * re ** (degree - 2)
    )
    hxy = degree * (degree - 2) * re ** (degree - 4) * dx * dy
    hyy = (
        degree * (degree - 2) * re ** (degree - 4) * dy**2
        + degree * re ** (degree - 2)
    )
    a = full_diag + hxx
    b = hxy
    d = full_diag + hyy
    return a, b, d


def assemble_df_phs_matrix(points: np.ndarray, degree: int) -> np.ndarray:
    a, b, d = df_phs_blocks(points, points, degree)
    return np.block([[a, b], [b, d]])


def apply_df_phs(
    points_eval: np.ndarray,
    points_train: np.ndarray,
    coeff_rbf: np.ndarray,
    degree: int,
) -> tuple[np.ndarray, np.ndarray]:
    n = points_train.shape[0]
    a, b, d = df_phs_blocks(points_eval, points_train, degree)
    c_u = coeff_rbf[:n]
    c_v = coeff_rbf[n:]
    return a @ c_u + b @ c_v, b @ c_u + d @ c_v


@dataclass
class LocalConfig:
    poly_order: int
    phs_degree: int
    stencil_size: int
    nugget: float = NUGGET


def fit_local_system(
    stencil_points: np.ndarray,
    u_stencil: np.ndarray,
    v_stencil: np.ndarray,
    config: LocalConfig,
):
    k = assemble_df_phs_matrix(stencil_points, config.phs_degree)
    p, center, scale, exps, transform = df_poly_basis_from_legendre(
        stencil_points, config.poly_order
    )
    saddle = np.block(
        [
            [k + config.nugget * np.eye(k.shape[0]), p],
            [p.T, np.zeros((p.shape[1], p.shape[1]))],
        ]
    )
    rhs = np.concatenate(
        [u_stencil, v_stencil, np.zeros(p.shape[1])]
    )
    coeffs = solve(saddle, rhs, assume_a="sym")
    return (
        coeffs[: k.shape[0]],
        coeffs[k.shape[0]:],
        center,
        scale,
        exps,
        transform,
    )


def eval_local_system(
    x_eval: np.ndarray,
    stencil_points: np.ndarray,
    coeff_rbf: np.ndarray,
    coeff_poly: np.ndarray,
    config: LocalConfig,
    center: np.ndarray,
    scale: float,
    exps,
    transform: np.ndarray,
):
    u_rbf, v_rbf = apply_df_phs(
        x_eval, stencil_points, coeff_rbf, config.phs_degree
    )
    if coeff_poly.size == 0:
        return u_rbf, v_rbf
    xi = (x_eval - center[None, :]) / scale
    raw_eval, _ = divfree_polynomial_stack(xi, config.poly_order)
    p_eval = (raw_eval / scale) @ transform
    poly_vals = p_eval @ coeff_poly
    n_eval = x_eval.shape[0]
    return u_rbf + poly_vals[:n_eval], v_rbf + poly_vals[n_eval:]


def sample_points(rng: np.random.Generator, n: int) -> np.ndarray:
    return distinct_uniform_points(rng, n, DOMAIN_LOW, DOMAIN_HIGH)


def output_dir() -> Path:
    path = Path(os.environ.get("RAGSYSTEM_OUTPUT_DIR", ".")).resolve()
    path.mkdir(parents=True, exist_ok=True)
    return path


def main() -> None:
    rng = np.random.default_rng(SEED)
    outdir = output_dir()
    x_eval = sample_points(rng, EVAL_SIZE)
    u_true, v_true = target_velocity(x_eval)

    u_errors = np.zeros((len(NODE_COUNTS), len(ORDERS)))
    v_errors = np.zeros_like(u_errors)
    combined_errors = np.zeros_like(u_errors)

    for oj, poly_order in enumerate(ORDERS):
        basis_count = divfree_poly_rank(2, poly_order, 10**9)
        stencil_size = 2 * math.ceil(basis_count) + 1
        phs_degree = min(
            poly_order + 1 if (poly_order + 1) % 2 == 1 else poly_order + 2,
            7,
        )
        config = LocalConfig(
            poly_order=poly_order,
            phs_degree=phs_degree,
            stencil_size=stencil_size,
        )
        print(
            f"Running poly_order={poly_order}, "
            f"phs_degree={phs_degree}, "
            f"stencil_size={stencil_size}"
        )

        for ni, n in enumerate(NODE_COUNTS):
            x_train = sample_points(rng, n)
            u_train, v_train = target_velocity(x_train)
            tree = cKDTree(x_train)
            _, assigned = tree.query(x_eval, k=1)
            u_pred = np.zeros_like(u_true)
            v_pred = np.zeros_like(v_true)

            for center_id in range(n):
                mask = assigned == center_id
                if not np.any(mask):
                    continue
                _, sten_idx = tree.query(
                    x_train[center_id],
                    k=min(config.stencil_size, n),
                )
                sten_idx = np.atleast_1d(sten_idx)
                stencil_points = x_train[sten_idx]
                (
                    coeff_rbf,
                    coeff_poly,
                    center,
                    scale,
                    exps,
                    transform,
                ) = fit_local_system(
                    stencil_points,
                    u_train[sten_idx],
                    v_train[sten_idx],
                    config,
                )
                u_loc, v_loc = eval_local_system(
                    x_eval[mask],
                    stencil_points,
                    coeff_rbf,
                    coeff_poly,
                    config,
                    center,
                    scale,
                    exps,
                    transform,
                )
                u_pred[mask] = u_loc
                v_pred[mask] = v_loc

            u_err = relative_l2(u_true, u_pred)
            v_err = relative_l2(v_true, v_pred)
            c_err = relative_l2(
                np.concatenate([u_true, v_true]),
                np.concatenate([u_pred, v_pred]),
            )
            u_errors[ni, oj] = u_err
            v_errors[ni, oj] = v_err
            combined_errors[ni, oj] = c_err
            print(
                f"  N={n:4d} -> "
                f"relL2(u)={u_err:.3e}, "
                f"relL2(v)={v_err:.3e}, "
                f"relL2(vec)={c_err:.3e}"
            )

    error_path = outdir / "hard_local_dfphs_poly_errors.txt"
    with error_path.open("w", encoding="utf-8") as fh:
        fh.write("# generator=scientific_driver_v1\n")
        fh.write("# domain=[-1,1]x[-1,1]\n")
        fh.write("# sampling=uniform_random\n")
        fh.write(f"# rng_seed={SEED}\n")
        fh.write(f"# evaluation_nodes={EVAL_SIZE}\n")
        fh.write(
            "# columns: poly_order N rel_l2_u rel_l2_v rel_l2_vec\n"
        )
        for oj, poly_order in enumerate(ORDERS):
            for ni, n in enumerate(NODE_COUNTS):
                fh.write(
                    f"{poly_order} {n} "
                    f"{u_errors[ni, oj]:.16e} "
                    f"{v_errors[ni, oj]:.16e} "
                    f"{combined_errors[ni, oj]:.16e}\n"
                )

    fig, axes = plt.subplots(
        1, 3, figsize=(14, 4.5), constrained_layout=True
    )
    labels = ["u", "v", "combined"]
    arrays = [u_errors, v_errors, combined_errors]
    for ax, arr, label in zip(axes, arrays, labels):
        for oj, poly_order in enumerate(ORDERS):
            ax.loglog(
                NODE_COUNTS,
                arr[:, oj],
                "-o",
                linewidth=1.8,
                label=f"order={poly_order}",
            )
        ax.set_xlabel("Number of interpolation nodes")
        ax.set_ylabel("Relative $L^2$ error")
        ax.set_title(label)
        ax.grid(True, which="both", alpha=0.25)
    axes[-1].legend(loc="best")
    fig.suptitle("Local DF-PHS + DF-polynomial interpolation ablation")
    fig.savefig(outdir / "hard_local_dfphs_poly_ablation.png", dpi=160)
    plt.close(fig)


if __name__ == "__main__":
    main()
